To sort the vector of words in ascending order based on the count of vowels in each word, you can follow these steps:
1. Define a function that takes a string as input and returns the count of vowels in that string. You can use a loop to iterate through each character in the string and check if it is a vowel.
2. Create a struct that contains two fields: the word and the count of vowels in that word. You can use this struct to store each word and its corresponding vowel count.
3. Create a vector of the struct defined in step 2 and populate it with the words and their vowel counts.
4. Use the std::sort algorithm to sort the vector based on the vowel count field of the struct. You can provide a lambda function as the second argument to std::sort to define the sorting criterion.
5. Iterate through the sorted vector and print out the words in ascending order based on their vowel count.
Here's some sample C++ code that implements these steps:
```
#include <iostream>
#include <vector>
#include <algorithm>
int count_vowels(const std::string& word) {
    int count = 0;
    for (char c : word) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            count++;
        }
    }
    return count;
}
struct WordVowelCount {
    std::string word;
    int vowel_count;
};
int main() {
    std::vector<std::string> words = {"gorilla", "zebra", "elephant", "giraffe", "lion"};
    std::vector<WordVowelCount> word_counts;
    for (const std::string& word : words) {
        int vowel_count = count_vowels(word);
        if (vowel_count > 0) {
            word_counts.push_back({word, vowel_count});
        }
    }
    std::sort(word_counts.begin(), word_counts.end(),
              [](const WordVowelCount& a, const WordVowelCount& b) {
                  return a.vowel_count < b.vowel_count;
              });
    for (const WordVowelCount& w : word_counts) {
        std::cout << w.word << std::endl;
    }
    return 0;
}
```
