imagettftext($image, 30, 0, 300, 100, $text_color, $font, $artist_name);
// Add the date and time of the show to the poster
$date_time = 'Date and Time';
imagettftext($image, 20, 0, 300, 150, $text_color, $font, $date_time);
// Save the poster as a JPEG image
