      val species = rs.getString("species")
      val height = rs.getDouble("height")
      val color = rs.getString("color")
      val plant = Plant(name, species, height, color)
      plants = plant :: plants
    }
    // Close the connection and return the list of Plant objects
    conn.close()
    plants
  }
