    // Identify the appropriate adjectives to modify and add the intensifiers
    List<string> adjectivesToModify = new List<string> { "hot" }; // Replace with actual adjectives from the sentence
    string enhancedSentence = sentence;
    foreach (string adjective in adjectivesToModify)
    {
        string intensifier = filteredIntensifiers.LastOrDefault(); // Choose the most intense intensifier
