```
import UIKit
class CarProductionChart: UIView {

    let barWidth: CGFloat = 30.0
    let barSpacing: CGFloat = 20.0
    let chartHeight: CGFloat = 300.0
    let chartWidth: CGFloat = 500.0
    let chartMargin: CGFloat = 50.0

    var data: [Int] = [1000, 800, 1200, 900, 600, 400, 300, 200, 100, 50]
    var labels: [String] = ["2010", "2011", "2012", "2013", "2014", "2015", "2016", "2017", "2018", "2019", "2020"]

    override func draw(_ rect: CGRect) {
        let context = UIGraphicsGetCurrentContext()

        // Set background color
        context?.setFillColor(UIColor.white.cgColor)
        context?.fill(rect)

        // Draw chart axes
        context?.setStrokeColor(UIColor.black.cgColor)
        context?.setLineWidth(2.0)
        context?.move(to: CGPoint(x: chartMargin, y: chartMargin))
        context?.addLine(to: CGPoint(x: chartMargin, y: chartHeight + chartMargin))
        context?.addLine(to: CGPoint(x: chartWidth + chartMargin, y: chartHeight + chartMargin))
        context?.strokePath()

        // Draw bars
        let barCount = data.count
        let totalBarsWidth = barWidth * CGFloat(barCount)
        let totalSpacingWidth = barSpacing * CGFloat(barCount - 1)
        let totalWidth = totalBarsWidth + totalSpacingWidth
        let startX = (chartWidth - totalWidth) / 2 + chartMargin
        let startY = chartHeight + chartMargin

        for i in 0..<barCount {
            let height = CGFloat(data[i]) / 10.0
            let barX = startX + (barWidth + barSpacing) * CGFloat(i)
            let barY = startY - height

            // Set bar color based on year
            let year = Int(labels[i])!
            var barColor = UIColor.blue
            if year == 2020 {
                barColor = UIColor.red
            } else if year >= 2019 {
                barColor = UIColor.orange
            }

            // Draw bar
            context?.setFillColor(barColor.cgColor)
            context?.fill(CGRect(x: barX, y: barY, width: barWidth, height: height))

            // Draw label
            let labelX = barX + barWidth / 2
            let labelY = startY + chartMargin / 2
            let label = labels[i]
            let labelAttributes: [NSAttributedString.Key: Any] = [
                .font: UIFont.systemFont(ofSize: 14),
                .foregroundColor: UIColor.black
            ]
            let labelSize = label.size(withAttributes: labelAttributes)
            let labelRect = CGRect(x: labelX - labelSize.width / 2, y: labelY - labelSize.height / 2, width: labelSize.width, height: labelSize.height)
            label.draw(in: labelRect, withAttributes: labelAttributes)
        }

        // Draw decrease line
        let startYearIndex = labels.firstIndex(of: "2019")!
        let endYearIndex = labels.firstIndex(of: "2020")!
        let startX = startX + (barWidth + barSpacing) * CGFloat(startYearIndex) + barWidth / 2
        let startY = startY - CGFloat(data[startYearIndex]) / 10.0
        let endX = startX + (barWidth + barSpacing) * CGFloat(endYearIndex - startYearIndex)
        let endY = startY - CGFloat(data[endYearIndex]) / 10.0 * 0.67

        context?.setStrokeColor(UIColor.red.cgColor)
        context?.setLineWidth(2.0)
        context?.move(to: CGPoint(x: startX, y: startY))
        context?.addLine(to: CGPoint(x: endX, y: endY))
        context?.strokePath()
    }
}
```
