Here is an example code that reads in a text file of Shakespeare's play "Hamlet" and analyzes the frequency of specific words and phrases while excluding certain words or phrases based on a predefined list:
```c++
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
// function to remove punctuation and convert to lowercase
std::string removePunctAndLower(const std::string& str) {
    std::string result;
    std::remove_copy_if(str.begin(), str.end(), std::back_inserter(result), std::ptr_fun<int, int>(&std::ispunct));
    std::transform(result.begin(), result.end(), result.begin(), ::tolower);
    return result;
}
int main() {
    // open the text file
    std::ifstream file("hamlet.txt");
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return 1;
    }
    // define the words and phrases to search for
    std::vector<std::string> searchTerms = {"to be or not to be", "the lady doth protest too much"};
    // define the words and phrases to exclude from the analysis
    std::vector<std::string> excludeTerms = {"the", "and", "of", "in", "a", "that", "to", "is", "with", "for", "on", "it", "this", "but", "not", "as", "be", "or"};
    // initialize a map to store the frequency of each search term
    std::map<std::string, int> frequencies;
    for (const auto& term : searchTerms) {
        frequencies[term] = 0;
    }
    // read the file line by line
    std::string line;
    while (std::getline(file, line)) {
        // remove punctuation and convert to lowercase
        line = removePunctAndLower(line);
        // search for each search term in the line
        for (const auto& term : searchTerms) {
            std::size_t pos = line.find(term);
            while (pos != std::string::npos) {
                // check if the term should be excluded
                bool exclude = false;
                for (const auto& excludeTerm : excludeTerms) {
                    if (line.substr(pos - excludeTerm.length() - 1, excludeTerm.length() + 1) == (" " + excludeTerm)) {
                        exclude = true;
                        break;
                    }
                }
                // increment the frequency if the term is not excluded
                if (!exclude) {
                    frequencies[term]++;
                }
                // search for the term again after the current position
                pos = line.find(term, pos + 1);
            }
        }
    }
    // print the frequency of each search term
    for (const auto& term : searchTerms) {
        std::cout << "\"" << term << "\" appears " << frequencies[term] << " times" << std::endl;
    }
    return 0;
}
```
This code uses a function `removePunctAndLower` to remove punctuation and convert each line of the text file to lowercase. It then searches for each search term in the line, and checks if it should be excluded based on the `excludeTerms` vector. If the term is not excluded, it increments the frequency in the `frequencies` map. Finally, it prints the frequency of each search term.
You can modify the `searchTerms` and `excludeTerms` vectors to include or exclude different words or phrases as needed.

