```c++
#include <iostream>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <hpdf.h>
#define PI 3.14159265358979323846
void draw_graph(HPDF_Page page, double (*func)(double), double x_min, double x_max, double y_min, double y_max, double step_size) {
    HPDF_Page_SetLineWidth(page, 1);
    HPDF_Page_SetRGBStroke(page, 0, 0, 1);
    HPDF_Page_MoveTo(page, x_min, func(x_min));
    for (double x = x_min + step_size; x <= x_max; x += step_size) {
        double y = func(x);
        if (y < y_min) {
            y = y_min;
        } else if (y > y_max) {
            y = y_max;
        }
        HPDF_Page_LineTo(page, x, y);
    }
    HPDF_Page_Stroke(page);
}
double sine_function(double x) {
    return sin(x);
}
int main() {
