```javascript
function describePlantColor(temperature) {
  let adjectives = [];
  if (temperature < 0) {
    adjectives.push("icy", "shimmering", "frigid");
  } else if (temperature >= 0 && temperature < 20) {
    adjectives.push("cool", "crisp", "frosty");
