  }
  // check for semantic coherence
  if (adjectives.length !== 3) {
    throw new Error("Invalid temperature input");
  }
  if (adjectives.includes("icy") && adjectives.includes("fiery")) {
    throw new Error("Incoherent adjectives");
  }
