```csharp
using System;
using System.IO;
using System.Text.RegularExpressions;
class Program
{
    static void Main()
    {
        string text = File.ReadAllText("mobydick.txt");
        // Retrieve the names of Captain Ahab and Ishmael
        string pattern = @"(Captain\s[A-Z]\w+\b).*?(Ishmael\b)";
        Match match = Regex.Match(text, pattern, RegexOptions.Singleline);
        if (match.Success)
        {
            Console.WriteLine("Main characters:");
            Console.WriteLine(match.Groups[1].Value + " - Captain of the Pequod");
            Console.WriteLine(match.Groups[2].Value + " - Narrator and sailor");
            // Retrieve the names of all significant characters
            pattern = @"([A-Z]\w+\b).*?(?:is|was)\s(?:a|the)\s(\b\w+\b)";
            MatchCollection matches = Regex.Matches(text, pattern, RegexOptions.Singleline);
            if (matches.Count > 0)
            {
                Console.WriteLine("\nAll significant characters:");
                foreach (Match m in matches)
                {
                    Console.WriteLine(m.Groups[1].Value + " - " + m.Groups[2].Value);
                }
            }
        }
        else
        {
            Console.WriteLine("No match found.");
        }
    }
}
```
This code uses a regular expression pattern that captures any capitalized word followed by "is", "was", "a", or "the", and then captures the following word as the character's role or background. The `(?:)` syntax is used to create non-capturing groups, so that only the significant characters' names and roles are captured.
Note that this code assumes that the text of Moby Dick is stored in a file named "mobydick.txt" in the same directory as the C# program. You may need to modify the file path if your text is stored elsewhere.

